    public static function startOCCULTATIONSVector(FlatBufferBuilder $builder, $numElems)
    {
        $builder->startVector(32, $numElems, 8);
    }

    /**
     * @param FlatBufferBuilder $builder
     * @param VectorOffset
     * @return void
     */
    public static function addEXCLUSIONS(FlatBufferBuilder $builder, $EXCLUSIONS)
    {
        $builder->addOffsetX(24, $EXCLUSIONS, 0);
    }

    /**
     * @param FlatBufferBuilder $builder
     * @param array offset array
     * @return int vector offset
     */
    public static function createEXCLUSIONSVector(FlatBufferBuilder $builder, array $data)
    {
        $builder->startVector(32, count($data), 8);
        for ($i = count($data) - 1; $i >= 0; $i--) {
            $builder->putOffset($data[$i]);
        }
        return $builder->endVector();
    }

    /**
     * @param FlatBufferBuilder $builder
     * @param int $numElems
     * @return void
     */
    public static function startEXCLUSIONSVector(FlatBufferBuilder $builder, $numElems)
    {
        $builder->startVector(32, $numElems, 8);
    }

    /**
     * @param FlatBufferBuilder $builder
     * @return int table offset
     */
    public static function endSKR(FlatBufferBuilder $builder)
    {
        $o = $builder->endObject();
        return $o;
    }

    public static function finishSKRBuffer(FlatBufferBuilder $builder, $offset)
    {
        $builder->finish($offset, "$SKR");
    }
}
